import fs from "node:fs";

const runPath = "harness/packages/scheduler/src/plain-dag-run.ts";
const indexPath = "harness/packages/scheduler/src/index.ts";
const testPath = "harness/packages/scheduler/src/invocation-capability-policy.test.ts";
const integrationPath = "harness/scripts/capability-invocation-enforcement.test.ts";

let run = fs.readFileSync(runPath, "utf8");

function replaceOnce(source, before, after, label) {
  const count = source.split(before).length - 1;
  if (count !== 1) {
    throw new Error(`${label}: expected exactly one anchor, found ${count}`);
  }
  return source.replace(before, after);
}

run = replaceOnce(
  run,
  `export interface PlainDagEffectRetryOptions {\n  /**\n   * Return true only when a stable Harness-owned idempotency key has already been\n   * bound to the logical external operation that the executor/integration will\n   * repeat. Merely having a persisted logical effect identity is not sufficient.\n   * The result is cached for the logical op so retry authority cannot change\n   * between scheduler attempts.\n   */\n  readonly hasBoundIdempotencyKey?: (context: PlainDagIdempotencyKeyRetryContext) => boolean;\n}\n\nexport interface PlainDagRunOptions {\n`,
  `export interface PlainDagEffectRetryOptions {\n  /**\n   * Return true only when a stable Harness-owned idempotency key has already been\n   * bound to the logical external operation that the executor/integration will\n   * repeat. Merely having a persisted logical effect identity is not sufficient.\n   * The result is cached for the logical op so retry authority cannot change\n   * between scheduler attempts.\n   */\n  readonly hasBoundIdempotencyKey?: (context: PlainDagIdempotencyKeyRetryContext) => boolean;\n}\n\n/** Structural shape intentionally satisfied by the host Core permission policy. */\nexport interface PlainDagCapabilityAuthorityEvaluation {\n  readonly decision: \"allow\" | \"deny\";\n  readonly denialReason?: \"explicitly-denied\" | \"not-granted\";\n}\n\n/** Current host-owned capability authority consulted immediately before invocation. */\nexport interface PlainDagCapabilityAuthority {\n  evaluate(\n    capability: ExecutionIrOpV1[\"behavior\"][\"requiredCapabilities\"][number],\n  ): PlainDagCapabilityAuthorityEvaluation;\n}\n\nexport interface PlainDagRunOptions {\n`,
  "insert invocation authority contract",
);

run = replaceOnce(
  run,
  `export interface PlainDagRunOptions {\n  readonly retry?: PlainDagRetryHooks;\n  readonly effectRetry?: PlainDagEffectRetryOptions;\n  /**\n`,
  `export interface PlainDagRunOptions {\n  readonly retry?: PlainDagRetryHooks;\n  readonly effectRetry?: PlainDagEffectRetryOptions;\n  /**\n   * Host-owned authority re-evaluated for every scheduler invocation attempt.\n   * Omission is fail-closed only for ops that actually require capabilities.\n   */\n  readonly capabilityAuthority?: PlainDagCapabilityAuthority;\n  /**\n`,
  "add run capability option",
);

run = replaceOnce(
  run,
  ` * writes require an explicit runtime assertion that a stable idempotency key is\n * bound to the integration operation. The same gate clamps adapter/internal\n * retries, so retry layers cannot bypass effect safety by sharing only a number.\n *\n * Retry waits are liveness tasks, not active execution tasks. They keep the run\n`,
  ` * writes require an explicit runtime assertion that a stable idempotency key is\n * bound to the integration operation. The same gate clamps adapter/internal\n * retries, so retry layers cannot bypass effect safety by sharing only a number.\n *\n * 5.7 re-checks each op's frozen required capability demand immediately before\n * every executor attempt. Current host authority is intentionally not cached\n * across attempts, so a revoked capability blocks a retry before it consumes a\n * new scheduler attempt or reaches executor/effect code. Graph deny remains a\n * one-way runtime restriction, while capability-free ops need no authority.\n *\n * Retry waits are liveness tasks, not active execution tasks. They keep the run\n`,
  "document 5.7 scheduler boundary",
);

run = replaceOnce(
  run,
  `      const operation = this.ir.ops[op];\n      if (operation === undefined) {\n        throw new RangeError(\`Execution IR op \${String(op)} is unavailable.\`);\n      }\n\n      const maxAttempts = operation.behavior.retry?.maxAttempts ?? 1;\n`,
  `      const operation = this.ir.ops[op];\n      if (operation === undefined) {\n        throw new RangeError(\`Execution IR op \${String(op)} is unavailable.\`);\n      }\n\n      this.assertInvocationCapabilities(op, operation);\n\n      const maxAttempts = operation.behavior.retry?.maxAttempts ?? 1;\n`,
  "gate executor invocation",
);

run = replaceOnce(
  run,
  `  private resolveRepeatAuthorization(\n    op: number,\n    operation: ExecutionIrOpV1,\n    maxAttempts: number,\n  ): boolean {\n`,
  `  private assertInvocationCapabilities(op: number, operation: ExecutionIrOpV1): void {\n    const seen = new Set<\n      ExecutionIrOpV1[\"behavior\"][\"requiredCapabilities\"][number]\n    >();\n\n    for (const capability of operation.behavior.requiredCapabilities) {\n      if (seen.has(capability)) {\n        continue;\n      }\n      seen.add(capability);\n\n      if (this.ir.policies.capabilities.deny.includes(capability)) {\n        throw new Error(\n          \`Run op \${String(op)} requires capability '\${capability}', but the compiled graph denies it.\`,\n        );\n      }\n\n      const evaluation = this.options.capabilityAuthority?.evaluate(capability);\n      if (evaluation?.decision === \"allow\") {\n        continue;\n      }\n\n      if (evaluation?.denialReason === \"explicitly-denied\") {\n        throw new Error(\n          \`Run op \${String(op)} requires capability '\${capability}', but current runtime authority explicitly denies it.\`,\n        );\n      }\n\n      throw new Error(\n        \`Run op \${String(op)} requires capability '\${capability}', but current runtime authority does not grant it.\`,\n      );\n    }\n  }\n\n  private resolveRepeatAuthorization(\n    op: number,\n    operation: ExecutionIrOpV1,\n    maxAttempts: number,\n  ): boolean {\n`,
  "add invocation capability gate",
);

fs.writeFileSync(runPath, run);

let index = fs.readFileSync(indexPath, "utf8");
index = replaceOnce(
  index,
  `Phase 5.3 adds effect-aware repeat authorization so numeric retry budget alone cannot authorize an uncertain external write, and adapter/internal retries share the same safety gate.`,
  `Phase 5.3 adds effect-aware repeat authorization so numeric retry budget alone cannot authorize an uncertain external write, and adapter/internal retries share the same safety gate. Phase 5.7 adds invocation-time capability re-checks against current host authority before executor attempts without caching authority across retries.`,
  "scheduler index phase note",
);
fs.writeFileSync(indexPath, index);

fs.writeFileSync(
  testPath,
  `import { describe, expect, it, vi } from \"vitest\";\n\nimport { SchedulerConcurrency } from \"./concurrency.js\";\nimport { PlainDagRun, type PlainDagCapabilityAuthority } from \"./plain-dag-run.js\";\nimport { createMockExecutionIr, createMockExecutionOp } from \"./testing.js\";\n\nfunction createRun(\n  requiredCapabilities: readonly string[],\n  executor: ConstructorParameters<typeof PlainDagRun>[2],\n  options: ConstructorParameters<typeof PlainDagRun>[3] = {},\n  deny: readonly string[] = [],\n): PlainDagRun {\n  const operation = createMockExecutionOp(\"capability-op\", [], {\n    behavior: { requiredCapabilities },\n  });\n  const base = createMockExecutionIr([operation]);\n  const plan = {\n    ...base,\n    policies: {\n      ...base.policies,\n      capabilities: { ...base.policies.capabilities, deny: [...deny] },\n    },\n  };\n  const scheduler = new SchedulerConcurrency(1);\n  return new PlainDagRun(plan, scheduler.createRun(plan), executor, options);\n}\n\ndescribe(\"invocation capability policy\", () => {\n  it(\"runs capability-free ops without requiring host authority\", async () => {\n    const executor = vi.fn();\n    const result = await createRun([], executor).execute();\n\n    expect(executor).toHaveBeenCalledOnce();\n    expect(result.attempts).toEqual([1]);\n  });\n\n  it(\"requires all declared capabilities and evaluates duplicates once per invocation\", async () => {\n    const evaluate = vi.fn((capability: string) => ({\n      decision: capability === \"fs:read\" || capability === \"network:http\" ? \"allow\" : \"deny\",\n    })) satisfies PlainDagCapabilityAuthority[\"evaluate\"];\n    const executor = vi.fn();\n\n    await createRun([\"fs:read\", \"fs:read\", \"network:http\"], executor, {\n      capabilityAuthority: { evaluate },\n    }).execute();\n\n    expect(executor).toHaveBeenCalledOnce();\n    expect(evaluate.mock.calls.map(([capability]) => capability)).toEqual([\"fs:read\", \"network:http\"]);\n  });\n\n  it(\"fails closed before consuming an attempt when required authority is absent\", async () => {\n    const executor = vi.fn();\n    const run = createRun([\"fs:read\"], executor);\n\n    await expect(run.execute()).rejects.toThrow(\n      \"Run op 0 requires capability 'fs:read', but current runtime authority does not grant it.\",\n    );\n\n    expect(executor).not.toHaveBeenCalled();\n    expect(run.snapshot().attempts).toEqual([0]);\n    expect(run.snapshot().attemptBudgetUsed).toEqual([0]);\n    expect(run.snapshot().readiness.ops).toEqual([{ op: 0, status: \"failed\" }]);\n  });\n\n  it(\"preserves explicit-deny reason while keeping denial terminal\", async () => {\n    const executor = vi.fn();\n    const run = createRun([\"fs:write\"], executor, {\n      capabilityAuthority: {\n        evaluate: () => ({ decision: \"deny\", denialReason: \"explicitly-denied\" }),\n      },\n    });\n\n    await expect(run.execute()).rejects.toThrow(\n      \"Run op 0 requires capability 'fs:write', but current runtime authority explicitly denies it.\",\n    );\n    expect(executor).not.toHaveBeenCalled();\n    expect(run.snapshot().attempts).toEqual([0]);\n  });\n\n  it(\"keeps compiled graph deny as a one-way restriction without consulting host authority\", async () => {\n    const evaluate = vi.fn(() => ({ decision: \"allow\" as const }));\n    const executor = vi.fn();\n    const run = createRun(\n      [\"network:http\"],\n      executor,\n      { capabilityAuthority: { evaluate } },\n      [\"network:http\"],\n    );\n\n    await expect(run.execute()).rejects.toThrow(\n      \"Run op 0 requires capability 'network:http', but the compiled graph denies it.\",\n    );\n    expect(evaluate).not.toHaveBeenCalled();\n    expect(executor).not.toHaveBeenCalled();\n  });\n\n  it(\"re-checks current authority on retry and honors revocation before another attempt starts\", async () => {\n    let granted = true;\n    const evaluate = vi.fn(() =>\n      granted\n        ? ({ decision: \"allow\" } as const)\n        : ({ decision: \"deny\", denialReason: \"explicitly-denied\" } as const),\n    );\n    let executorCalls = 0;\n    const operation = createMockExecutionOp(\"revoked-retry\", [], {\n      behavior: {\n        requiredCapabilities: [\"network:http\"],\n        retry: { maxAttempts: 2, backoffMs: 0 },\n      },\n    });\n    const plan = createMockExecutionIr([operation]);\n    const scheduler = new SchedulerConcurrency(1);\n    const run = new PlainDagRun(\n      plan,\n      scheduler.createRun(plan),\n      () => {\n        executorCalls += 1;\n        granted = false;\n        throw new Error(\"transient provider failure\");\n      },\n      { capabilityAuthority: { evaluate } },\n    );\n\n    await expect(run.execute()).rejects.toThrow(\n      \"Run op 0 requires capability 'network:http', but current runtime authority explicitly denies it.\",\n    );\n\n    expect(executorCalls).toBe(1);\n    expect(evaluate).toHaveBeenCalledTimes(2);\n    expect(run.snapshot().attempts).toEqual([1]);\n    expect(run.snapshot().attemptBudgetUsed).toEqual([1]);\n  });\n\n  it(\"checks permission before effect retry proof or executor code\", async () => {\n    const executor = vi.fn();\n    const hasBoundIdempotencyKey = vi.fn(() => true);\n    const operation = createMockExecutionOp(\"denied-write\", [], {\n      behavior: {\n        primitiveFamily: \"effect\",\n        effect: \"external-write\",\n        idempotency: \"idempotency-key\",\n        recovery: \"reconcile\",\n        requiredCapabilities: [\"fs:write\"],\n        retry: { maxAttempts: 2 },\n      },\n    });\n    const plan = createMockExecutionIr([operation]);\n    const scheduler = new SchedulerConcurrency(1);\n    const run = new PlainDagRun(plan, scheduler.createRun(plan), executor, {\n      capabilityAuthority: {\n        evaluate: () => ({ decision: \"deny\", denialReason: \"not-granted\" }),\n      },\n      effectRetry: { hasBoundIdempotencyKey },\n    });\n\n    await expect(run.execute()).rejects.toThrow(\n      \"Run op 0 requires capability 'fs:write', but current runtime authority does not grant it.\",\n    );\n    expect(hasBoundIdempotencyKey).not.toHaveBeenCalled();\n    expect(executor).not.toHaveBeenCalled();\n    expect(run.snapshot().attempts).toEqual([0]);\n  });\n});\n`,
);

fs.writeFileSync(
  integrationPath,
  `import { describe, expect, it, vi } from \"vitest\";\n\nimport { CapabilityPermissionPolicy } from \"@zet-harness/core\";\nimport { PlainDagRun, SchedulerConcurrency } from \"@zet-harness/scheduler\";\nimport { createMockExecutionIr, createMockExecutionOp } from \"@zet-harness/scheduler/testing\";\n\nfunction runtimePlan(capability: string) {\n  return createMockExecutionIr([\n    createMockExecutionOp(\"runtime-policy\", [], {\n      behavior: { requiredCapabilities: [capability] },\n    }),\n  ]);\n}\n\ndescribe(\"CapabilityPermissionPolicy invocation integration\", () => {\n  it(\"lets the real host policy authorize an exact required capability\", async () => {\n    const policy = new CapabilityPermissionPolicy({ granted: [\"fs:read\"] });\n    const plan = runtimePlan(\"fs:read\");\n    const scheduler = new SchedulerConcurrency(1);\n    const executor = vi.fn();\n\n    await new PlainDagRun(plan, scheduler.createRun(plan), executor, {\n      capabilityAuthority: policy,\n    }).execute();\n\n    expect(executor).toHaveBeenCalledOnce();\n  });\n\n  it(\"preserves exact-match and explicit-deny semantics at invocation time\", async () => {\n    const exactOnly = new CapabilityPermissionPolicy({ granted: [\"fs:read\"] });\n    const exactPlan = runtimePlan(\"fs:read:metadata\");\n    const exactScheduler = new SchedulerConcurrency(1);\n    const exactExecutor = vi.fn();\n\n    await expect(\n      new PlainDagRun(exactPlan, exactScheduler.createRun(exactPlan), exactExecutor, {\n        capabilityAuthority: exactOnly,\n      }).execute(),\n    ).rejects.toThrow(\"current runtime authority does not grant it\");\n    expect(exactExecutor).not.toHaveBeenCalled();\n\n    const denied = new CapabilityPermissionPolicy({\n      granted: [\"network:http\"],\n      denied: [\"network:http\"],\n    });\n    const deniedPlan = runtimePlan(\"network:http\");\n    const deniedScheduler = new SchedulerConcurrency(1);\n    const deniedExecutor = vi.fn();\n\n    await expect(\n      new PlainDagRun(deniedPlan, deniedScheduler.createRun(deniedPlan), deniedExecutor, {\n        capabilityAuthority: denied,\n      }).execute(),\n    ).rejects.toThrow(\"current runtime authority explicitly denies it\");\n    expect(deniedExecutor).not.toHaveBeenCalled();\n  });\n});\n`,
);

console.log("Harness 5.7 implementation patch applied.");
